15	/**
16	 * The policyholder bears a deductible on each damaged item, so an incident
17	 * that damages several items bears it several times -- once per damage
18	 * entry, which is why the payout is accumulated per entry rather than off
19	 * the incident's total.
20	 */
21	const DEDUCTIBLE = 100;
22	
23	/**
24	 * A payout is money the MHPCO pays out, so it floors at nothing: the
25	 * deductible can reduce a payout to zero, but a damage smaller than the
26	 * deductible never turns into a debt owed to the MHPCO.
27	 */
28	const NOTHING_PAID_OUT = 0;
29	
30	/** What one damage settles at: the reimbursed share, less the deductible. */
31	function payoutForDamage(items: readonly Item[], damage: Damage): number {
32	  const reimbursed =
33	    damage.amount * reimbursementRateOf(damagedItem(items, damage.itemType));
34	  return Math.max(reimbursed - DEDUCTIBLE, NOTHING_PAID_OUT);
35	}
36	
37	/**
38	 * What an incident settles at: each damage entry is settled on its own --
39	 * under the clauses of the item it hit, and bearing its own deductible --
40	 * and the entries accumulate. An incident that damages nothing settles at
41	 * nothing.
42	 */
43	function incidentPayout(
44	  items: readonly Item[],
45	  damages: readonly Damage[],
46	): number {
47	  return damages.reduce(
48	    (total, damage) => total + payoutForDamage(items, damage),
49	    NOTHING_PAID_OUT,
50	  );
51	}
52	
53	/**
54	 * What the policy's cap still allows after a payout has been drawn against
55	 * it. The cap is a separate limit from the clauses and the deductible: those
56	 * decide what the MHPCO owes for a damage, whereas the cap decides how much
57	 * a policy can still pay out at all, and the MHPCO revises the two on their
58	 * own schedules -- which is why drawing against the cap is stated here,
59	 * apart from what a damage settles at.
60	 *
61	 * Every active example settles within the cap, so all the cap knows so far
62	 * is that a payout draws it down.
63	 */
64	/**
65	 * The policy pays no more than its cap still allows, so a payout the cap
66	 * cannot cover is reduced to what is left of it.
67	 */
68	function drawnAgainstCap(capBeforeClaim: number, desiredPayout: number): number {
69	  return Math.min(desiredPayout, capBeforeClaim);
70	}
71	
72	/**
73	 * Settling an incident against the policy that covers it: what the incident
74	 * settles at, and what it leaves of the policy's cap.
75	 */
76	export function claim(
77	  items: readonly Item[],
78	  damages: readonly Damage[],
79	  capBeforeClaim: number,
80	): ClaimResult {
81	  const payout = drawnAgainstCap(
82	    capBeforeClaim,
83	    incidentPayout(items, damages),
84	  );
85	  return { payout, remainingCap: capBeforeClaim - payout };
86	}
